// wf.gateway.auth > "Prepare request"
// Input: one webhook item whose json has {headers, params, query, body} plus
// json.route = {method, template, require_user, idempotent, required_consents, roles}
// and json.t0 (ms). The raw body is in binary.data (Webhook option rawBody).
// Pure helpers shared by Code nodes and unit tests (n8n/tests/canonical.test.js).
// n8n/build.py inlines this file into Code nodes that contain the marker
// "/* @include lib/canonical.js */". Keep it free of n8n globals.

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

// Path from a route template like "/v1/listings/:id/analyze" and the params object.
function buildPath(template, params) {
  return String(template || '').replace(/:([A-Za-z_][A-Za-z0-9_]*)/g,
    (_, k) => encodeURIComponent(String((params || {})[k] ?? '')));
}

// Canonical query string: encodeURIComponent(key)=encodeURIComponent(value),
// pairs sorted by encoded key (stable, so repeated keys keep their order).
// Returns { ok: true, value } or { ok: false, field } for nested values.
function canonicalQuery(query) {
  const pairs = [];
  for (const [k, v] of Object.entries(query || {})) {
    for (const x of (Array.isArray(v) ? v : [v])) {
      if (typeof x !== 'string') return { ok: false, field: k };
      pairs.push([encodeURIComponent(k), encodeURIComponent(x)]);
    }
  }
  pairs.sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0));
  return { ok: true, value: pairs.map(([k, v]) => `${k}=${v}`).join('&') };
}

// First non-empty string value of a header (Node lower-cases header names).
function header(headers, name) {
  const v = (headers || {})[name];
  if (Array.isArray(v)) return v.length ? String(v[0]) : null;
  return typeof v === 'string' && v.length > 0 ? v : null;
}

// Random v4-style uuid for correlation ids when the caller sent none.
// Not used for anything security-relevant (Code nodes cannot load node:crypto).
function correlationId() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = (Math.random() * 16) | 0;
    return (c === 'x' ? r : (r & 0x3) | 0x8).toString(16);
  });
}

function envelopeError(requestId, code, message, details) {
  return { request_id: requestId, error: { code, message, details: details || [] } };
}

const ERROR_STATUS = {
  UNAUTHENTICATED: 401, FORBIDDEN: 403, VALIDATION_FAILED: 422, NOT_FOUND: 404,
  CONSENT_REQUIRED: 403, RATE_LIMITED: 429, CONFLICT: 409, UPSTREAM_UNAVAILABLE: 503,
  POLICY_BLOCKED: 403, INTERNAL: 500, PAYLOAD_TOO_LARGE: 413, EXTRACTION_FAILED: 422,
};

if (typeof module !== 'undefined') {
  module.exports = { UUID_RE, buildPath, canonicalQuery, header, correlationId, envelopeError, ERROR_STATUS };
}


const item = $input.first();
const j = item.json;
const h = j.headers || {};
const route = j.route || {};
const ridHeader = header(h, 'x-request-id');
const request_id = ridHeader && UUID_RE.test(ridHeader) ? ridHeader.toLowerCase() : correlationId();
const base = {
  request_id, route, t0: j.t0 || Date.now(), lang: header(h, 'accept-language'),
  input: { params: j.params || {}, query: j.query || {} },
};
const reject = (status, code, message, details = [], reason = null) =>
  [{ json: { ...base, ok: false, status, error: { code, message, details }, log: { reason } } }];

const q = canonicalQuery(j.query);
if (!q.ok) return reject(422, 'VALIDATION_FAILED', 'Nested query parameters are not supported', [{ field: q.field }], 'nested_query');

let body_b64 = '';
if (item.binary && item.binary.data) {
  const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
  body_b64 = buf.toString('base64');
}

// IPs for rate limiting (app.gateway_check picks one): the signed X-Client-Ip
// sent by the website server, and the address the proxy saw (X-Forwarded-For,
// set by Caddy, which does not trust an incoming X-Forwarded-For).
const clientIp = header(h, 'x-client-ip');
const xff = (header(h, 'x-forwarded-for') || '').split(',').pop().trim();

const check = {
  key_id: header(h, 'x-key-id'),
  timestamp: header(h, 'x-timestamp'),
  method: String(route.method || '').toUpperCase(),
  path: buildPath(route.template, j.params),
  query: q.value,
  request_id: ridHeader,
  user_id: header(h, 'x-user-id') || '',
  idempotency_key: header(h, 'x-idempotency-key') || '',
  client_ip: clientIp || '',
  body_b64,
  signature: header(h, 'x-signature'),
  network_ip: xff || '',
};

return [{ json: { ...base, ok: true, check, body: j.body ?? null, content_type: header(h, 'content-type') } }];

// wf.gateway.auth > "Decide"
// Input: {g} from app.gateway_check. Applies the gateway rules in order and
// returns ok:true with the request context, or ok:false with an error envelope.
const prep = $('Prepare request').first().json;
const g = $input.first().json.g || {};
const route = prep.route || {};
const base = { request_id: prep.request_id, route, t0: prep.t0, lang: prep.lang };
const reject = (status, code, message, details = [], reason = null) =>
  [{ json: { ...base, ok: false, status, error: { code, message, details }, log: { reason } } }];

const v = g.verify || {};
const ctx = g.context || {};
const s = ctx.settings || {};
const rate = g.rate || {};
const limitIp = Number(s['gateway.rate_limit_ip_per_min'] ?? 120);
const limitUser = Number(s['gateway.rate_limit_user_per_min'] ?? 60);
const retryAfter = 60 - (Math.floor(Date.now() / 1000) % 60);

// 1. Per-IP limit first: it also counts requests with bad signatures.
if (Number(rate.ip) > limitIp) return reject(429, 'RATE_LIMITED', 'Too many requests', [{ retry_after_s: retryAfter }], 'ip_limit');

// 2. Signature, timestamp window, replay.
if (!v.ok) {
  if (v.reason === 'stale_timestamp') {
    return reject(401, 'UNAUTHENTICATED', 'X-Timestamp is outside the accepted window', [{ server_time: v.server_time }], v.reason);
  }
  return reject(401, 'UNAUTHENTICATED', 'Request signature could not be verified', [], v.reason || 'unknown');
}

// 3. Per-user limit (counted only for verified requests).
if (rate.user != null && Number(rate.user) > limitUser) {
  return reject(429, 'RATE_LIMITED', 'Too many requests', [{ retry_after_s: retryAfter }], 'user_limit');
}

// 4. User, role, consent.
const uid = prep.check.user_id;
const user = ctx.user || null;
if (uid && !user) return reject(401, 'UNAUTHENTICATED', 'Unknown user', [], 'unknown_user');
if (user && user.deleted) return reject(403, 'FORBIDDEN', 'This account has been erased', [], 'erased_user');
if (route.require_user && !user) return reject(401, 'UNAUTHENTICATED', 'X-User-Id is required for this endpoint', [], 'user_required');
if (Array.isArray(route.roles) && route.roles.length > 0 && !(user && route.roles.includes(user.role))) {
  return reject(403, 'FORBIDDEN', 'Your role does not allow this action', [], 'role');
}
for (const purpose of route.required_consents || []) {
  if (!ctx.consents || ctx.consents[purpose] !== true) {
    return reject(403, 'CONSENT_REQUIRED', 'Consent is required for this action', [{ purpose }], 'consent');
  }
}

// 5. Body shape for methods that carry one.
if (['POST', 'PUT', 'PATCH'].includes(String(route.method).toUpperCase())) {
  if (!String(prep.content_type || '').toLowerCase().startsWith('application/json')) {
    return reject(422, 'VALIDATION_FAILED', 'Content-Type must be application/json', [], 'content_type');
  }
  if (prep.body === null || typeof prep.body !== 'object' || Array.isArray(prep.body)) {
    return reject(422, 'VALIDATION_FAILED', 'Body must be a JSON object', [], 'body_shape');
  }
}

// 6. Idempotency key on state-changing routes.
const idem = prep.check.idempotency_key;
if (route.idempotent && !/^[A-Za-z0-9_.:-]{8,128}$/.test(idem)) {
  return reject(422, 'VALIDATION_FAILED', 'X-Idempotency-Key is required: 8 to 128 characters from A-Z a-z 0-9 _ . : -', [], 'idempotency_key');
}

return [{
  json: {
    ...base,
    ok: true,
    ctx: {
      request_id: prep.request_id, key_id: v.key_id, user_id: uid || null, user,
      consents: ctx.consents || {}, lang: prep.lang, client_ip: prep.check.client_ip || null,
      params: prep.input.params, query: prep.input.query, body: prep.body,
    },
    idempotency: route.idempotent
      ? { scope: `${v.key_id}:${uid || 'anon'}`, key: idem, route: `${String(route.method).toUpperCase()} ${route.template}`, body_sha256: v.body_sha256 }
      : null,
  },
}];

// wf.gateway.auth > "Apply idempotency"
// Input: {r} from app.idempotency_begin. Passes the request on, returns the
// stored response for a finished duplicate, or rejects a conflicting reuse.
const d = $('Decide').first().json;
const r = $input.first().json.r || {};
const reject = (status, code, message, reason) =>
  [{ json: { request_id: d.request_id, route: d.route, t0: d.t0, lang: d.lang, ok: false, status,
             error: { code, message, details: [] }, log: { reason }, idempotency: null } }];

if (r.state === 'new') return [{ json: { ...d, idempotency_took_over: !!r.took_over } }];
if (r.state === 'replay') {
  return [{ json: { request_id: d.request_id, route: d.route, t0: d.t0, lang: d.lang, ok: false,
                    replay: true, status: r.response_status, response: r.response_body,
                    log: { reason: 'idempotent_replay' }, idempotency: d.idempotency } }];
}
if (r.state === 'conflict') return reject(409, 'CONFLICT', 'X-Idempotency-Key was already used for a different request', 'idempotency_conflict');
return reject(409, 'CONFLICT', 'A request with this X-Idempotency-Key is still being processed', 'idempotency_in_progress');

// wf.gateway.auth > "Database unavailable"
// Error output of a Postgres node: no partial writes happened, answer 503.
const prep = $('Prepare request').first().json;
// Text of the error carried by an item on a node's error output.
// n8n puts either a string or an object {message, description, ...} in json.error.
function errorText(json) {
  const e = json && (json.error !== undefined ? json.error : json);
  if (e == null) return '';
  if (typeof e === 'string') return e;
  const parts = [e.message, e.description, e.cause && e.cause.message].filter((x) => typeof x === 'string' && x);
  return parts.length ? parts.join(' | ') : JSON.stringify(e);
}
// Postgres error details echo the offending value, e.g. Key (email)=(a@b.c).
// Values are removed before anything is logged.
function redactPg(msg) {
  return String(msg || '').replace(/\)=\([^)]*\)/g, ')=(redacted)');
}
if (typeof module !== 'undefined') module.exports = { errorText, redactPg };

const msg = errorText($input.first().json);
return [{ json: { request_id: prep.request_id, route: prep.route, t0: prep.t0, lang: prep.lang, ok: false, status: 503,
                  error: { code: 'UPSTREAM_UNAVAILABLE', message: 'A backend dependency is unavailable', details: [] },
                  log: { reason: 'database_error', detail: redactPg(msg).slice(0, 300) } } }];
